<script setup>
import { ref,computed,onMounted,onUnmounted,watch,provide } from 'vue';
import { useRoute } from 'vue-router';
import { api } from '../../services/api.js';
import { money,dateTime,statusLabels,whatsappUrl } from '../../services/format.js';
import { normalizeDesign,designStyle } from '../../services/design.js';
import { StoreCopy } from '../../services/storeCopy.js';
import { StoreTextLayout } from '../../services/storeNavigation.js';
import { storefrontKey } from '../../services/storefront.js';
import { cartFor } from '../../services/cart.js';
import { useStoreBranding } from '../../services/storeBranding.js';
import { notify } from '../../services/notifications.js';
import ProductImage from '../../components/ProductImage.vue';
import Icon from '../../components/Icon.vue';
import { StoreThemeService, browserStoreThemeEnvironment } from '../../services/storeTheme.js';
import StoreNavbar from '../../components/StoreNavbar.vue';
const route=useRoute(),data=ref(null),loading=ref(true),error=ref(''),refreshing=ref(false),uploading=ref(false),receiptFile=ref(null),verifying=ref(false);
const token=ref(typeof route.query.token==='string'?route.query.token:''),order=computed(()=>data.value?.order),store=computed(()=>data.value?.store),design=computed(()=>normalizeDesign(store.value?.design));
const copy=new StoreCopy(()=>design.value);
const storeTheme=new StoreThemeService(browserStoreThemeEnvironment()),appearance=storeTheme.state;
const colorMode=computed(()=>storeTheme.resolved(design.value));
watch(()=>store.value?._id||store.value?.slug,identifier=>storeTheme.useStore(identifier),{immediate:true});
useStoreBranding(design,{appearance:()=>appearance.deviceAppearance,preference:()=>appearance.preference});
let timer,active=true,requestId=0,pollCount=0,inFlight=0,catalogRequestId=0;
const navbarHeight=ref(82),categories=ref([]),featuredProducts=ref([]),preview=ref(false),cart=computed(()=>cartFor(store.value?.slug||'tracking'));
function storeLink(suffix=''){return{path:'/t/'+store.value.slug+suffix,query:{}};}
provide(storefrontKey,{store,design,categories,featuredProducts,cart,isPreview:preview,link:storeLink,storeTheme,colorMode});
watch(()=>store.value?.slug,async slug=>{
 const sequence=++catalogRequestId;categories.value=[];featuredProducts.value=[];if(!slug)return;
 try{const catalog=await api.get('/public/stores/'+slug+'?limit=1');if(active&&sequence===catalogRequestId){categories.value=catalog.categories||[];featuredProducts.value=catalog.featuredProducts||[];}}catch{}
});
const needsRefresh=computed(()=>{if(!order.value||order.value.status==='cancelled')return false;if(order.value.status!=='paid')return true;return order.value.items.some(i=>i.type==='physical')&&order.value.fulfillmentStatus!=='delivered'||order.value.items.some(i=>i.type==='digital')&&order.value.digitalDeliveryStatus!=='sent';});
const final=computed(()=>['paid','cancelled'].includes(order.value?.status));
function path(suffix=''){return `/public/orders/${route.params.id}${suffix}?token=${encodeURIComponent(token.value)}`;}
async function load(silent=false){
 if(!active)return;
 const seq=++requestId;inFlight++;
 if(!silent)loading.value=true;error.value='';
 try{
  if(!token.value)throw new Error('Necesitás el enlace privado de tu pedido para ver esta página.');
  const result=await api.get(path());
  if(active&&seq===requestId)data.value=result;
 }catch(e){if(active&&seq===requestId)error.value=e.message;}
 finally{inFlight--;if(active&&seq===requestId){loading.value=false;refreshing.value=false;}}
}
async function refresh(){pollCount=0;refreshing.value=true;await load(true);}
async function upload(){if(!receiptFile.value){notify.error('Elegí un comprobante para adjuntar.');return;}if(receiptFile.value.size>8*1024*1024){notify.error('El comprobante debe pesar menos de 8 MB.');return;}uploading.value=true;try{const form=new FormData();form.append('file',receiptFile.value);await api.upload(path('/receipt'),form);notify.success('Comprobante enviado. El vendedor revisará tu pago.');receiptFile.value=null;await load(true);}catch(e){notify.error(e.message);}finally{uploading.value=false;}}
async function verify(){verifying.value=true;try{await api.post(path('/verify-payment'),{});await load(true);if(order.value?.status!=='paid')notify.info('El pago aún no figura aprobado. Podés consultar nuevamente en unos instantes.');}catch(e){notify.error(e.message);}finally{verifying.value=false;}}
async function copyTracking(){try{await navigator.clipboard.writeText(location.origin+`/pedido/${route.params.id}?token=${encodeURIComponent(token.value)}`);notify.success('Enlace privado copiado.');}catch{notify.info('Copiá el enlace desde la barra de direcciones.');}}
watch(()=>[route.params.id,route.query.token],()=>{token.value=typeof route.query.token==='string'?route.query.token:'';data.value=null;pollCount=0;load();},{immediate:true});
onMounted(()=>{timer=setInterval(()=>{if(active&&!document.hidden&&needsRefresh.value&&!inFlight&&pollCount<120){pollCount++;load(true);}},15000);});onUnmounted(()=>{active=false;requestId++;clearInterval(timer);storeTheme.dispose();});
</script>
<template><div v-if="loading" class="loading" style="min-height:100vh"><span class="spinner"></span>Buscando tu pedido…</div><div v-else-if="error&&!order" class="store-unavailable"><Icon name="package" :size="45"/><h1>No pudimos abrir este pedido.</h1><p>{{error}}</p><button class="btn btn-primary" @click="load()">Reintentar</button></div><div v-else-if="order" class="storefront order-tracking" :data-store-theme="colorMode" :dir="design.brand.textDirection" :style="{...designStyle(design,appearance.deviceAppearance,appearance.preference),'--store-header-offset':navbarHeight+'px'}"><StoreNavbar @height="navbarHeight=$event"/><div class="tracking-private"><Icon name="shield" :size="15"/> Seguimiento privado</div><main class="tracking-main" :style="StoreTextLayout.style(design.checkout.textAlign)" :dir="StoreTextLayout.direction(design.checkout.textDirection)"><div class="tracking-hero"><span class="tracking-status-icon" :class="order.status"><Icon :name="order.status==='paid'?'check':order.status==='cancelled'?'close':'package'" :size="32"/></span><span class="store-eyebrow">{{copy.text('trackingEyebrow')}} {{order.number}}</span><h1>{{order.status==='cancelled'?'El pedido fue cancelado.':order.status==='paid'?design.checkout.thankYouTitle:'¡Recibimos tu pedido!'}}</h1><p>{{order.status==='paid'?design.checkout.thankYouMessage:order.status==='cancelled'?'Si ya realizaste un pago, contactá al vendedor para revisar la situación.':'Guardá este enlace para consultar el estado y los próximos pasos.'}}</p><div class="tracking-badges"><span class="badge" :class="order.status==='paid'?'badge-success':order.status==='cancelled'?'badge-danger':'badge-warning'">{{statusLabels[order.status]}}</span><span class="badge badge-info">{{statusLabels[order.fulfillmentStatus]}}</span></div><p v-if="error" class="notice error">{{error}}</p></div><div class="tracking-grid"><div class="stack"><section v-if="order.payment.type==='mercadopago'&&!final" class="tracking-card"><h2>Completá tu pago</h2><p>Continuá en Mercado Pago. El pedido se confirmará cuando el proveedor informe la aprobación.</p><div class="row wrap"><a v-if="data.checkoutUrl||order.checkoutUrl" :href="data.checkoutUrl||order.checkoutUrl" class="store-button">Ir a Mercado Pago <Icon name="arrow-right" :size="17"/></a><button class="store-button secondary" :disabled="verifying" @click="verify">{{verifying?'Consultando…':'Ya pagué, verificar'}}</button></div><p v-if="order.reservationExpiresAt" class="tracking-hint">La reserva vence el {{dateTime(order.reservationExpiresAt)}}.</p></section><section v-if="order.payment.type==='transfer'" class="tracking-card"><h2>Pago por transferencia</h2><div class="bank-details"><div v-for="(label,key) in {holder:'Titular',bank:'Banco',cbu:'CBU / CVU',alias:'Alias',cuit:'CUIT / CUIL'}" :key="key"><template v-if="order.payment.bank?.[key]"><span>{{label}}</span><strong>{{order.payment.bank[key]}}</strong></template></div><div><span>Importe exacto</span><strong>{{money(order.total)}}</strong></div></div><p v-if="order.payment.instructions" class="tracking-instructions">{{order.payment.instructions}}</p><div v-if="order.receipt" class="notice success">Comprobante recibido: {{order.receipt.name}} · {{dateTime(order.receipt.uploadedAt)}}.</div><form v-if="!final" class="receipt-form" @submit.prevent="upload"><label class="receipt-upload"><Icon name="upload" :size="24"/><strong>{{receiptFile?.name||'Adjuntá tu comprobante'}}</strong><span>JPG, PNG, WebP o PDF · Hasta 8 MB</span><input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" @change="receiptFile=$event.target.files[0]" aria-label="Seleccionar comprobante"/></label><button class="store-button" :disabled="uploading||!receiptFile">{{uploading?'Enviando…':order.receipt?'Actualizar comprobante':'Enviar comprobante'}}</button></form><p v-if="!final" class="tracking-hint">El vendedor revisará la transferencia y confirmará el pago.</p></section><section v-if="order.payment.type==='cash'" class="tracking-card"><h2>{{order.payment.name}}</h2><p>{{order.payment.instructions||'Coordiná el pago con el vendedor. El estado se actualizará cuando confirme el cobro.'}}</p></section><section class="tracking-card"><h2>{{copy.text('trackingDeliveryTitle')}}</h2><div class="tracking-delivery"><Icon :name="order.delivery.type==='pickup'?'store':order.delivery.type==='digital'?'mail':'truck'" :size="25"/><div><strong>{{order.delivery.name}}</strong><p>{{order.delivery.description}}</p><p v-if="order.customer.address">{{order.customer.address}}<br>{{order.customer.city}} {{order.customer.postalCode}}</p></div></div><p v-if="order.items.some(i=>i.type==='digital')" class="notice">{{order.digitalDeliveryStatus==='sent'?'Los enlaces digitales ya fueron enviados a '+order.customer.email+'.':order.digitalDeliveryStatus==='failed'?'El envío del correo está pendiente de reintento. Contactá al vendedor si no lo recibís.':'Los enlaces digitales se enviarán a '+order.customer.email+' cuando se confirme el pago.'}}</p></section><section class="tracking-card tracking-contact"><h2>{{copy.text('trackingContactTitle')}}</h2><p>Contactá a la tienda y mencioná el número {{order.number}}.</p><div class="row wrap"><a v-if="store?.contact?.whatsapp||store?.contact?.phone" class="store-button secondary" :href="whatsappUrl(store.contact.whatsapp||store.contact.phone,'Hola, tengo una consulta sobre mi pedido '+order.number)" target="_blank" rel="noopener"><Icon name="whatsapp" :size="19"/>WhatsApp</a><a v-if="store?.contact?.email" class="store-button secondary" :href="'mailto:'+store.contact.email+'?subject='+encodeURIComponent('Consulta pedido '+order.number)"><Icon name="mail" :size="18"/>Correo</a></div></section></div><aside class="tracking-card tracking-summary"><span class="store-eyebrow">TU ELECCIÓN</span><h2>{{copy.text('trackingSummaryTitle')}}</h2><div v-for="(item,index) in order.items" :key="index" class="tracking-item"><div class="tracking-item-image"><ProductImage :src="item.image" :name="item.name" :type="item.type"/></div><div><strong>{{item.name}}</strong><small>{{item.variantName}} · {{item.quantity}} unidad(es)</small></div><b>{{money(item.lineTotal)}}</b></div><div class="checkout-summary-totals"><p><span>Productos</span><strong>{{money(order.subtotal)}}</strong></p><p><span>{{copy.text('delivery')}}</span><strong>{{order.deliveryCost?money(order.deliveryCost):copy.text('freeDelivery')}}</strong></p><p class="grand-total"><span>{{copy.text('total')}}</span><strong>{{money(order.total)}}</strong></p></div><p class="tracking-hint">Creado el {{dateTime(order.createdAt)}}<br>{{order.customer.name}}<br>{{order.customer.email}}</p><button class="store-button secondary" @click="copyTracking"><Icon name="copy" :size="17"/>Copiar enlace privado</button><button class="store-refresh" :disabled="refreshing" @click="refresh">{{refreshing?'Actualizando…':'Actualizar estado'}}</button></aside></div><RouterLink v-if="store" :to="'/t/'+store.slug" class="store-continue"><Icon name="arrow-left" :size="17"/> {{copy.text('backToStore')}}</RouterLink></main></div></template>

<style scoped>
.tracking-private{display:flex;align-items:center;justify-content:center;gap:8px;color:var(--store-muted);font-size:.68rem;padding:17px 20px 0}.tracking-summary{top:calc(var(--store-header-offset,82px) + 24px)}.tracking-grid>*{min-width:0}.tracking-main :is(h1,h2,p){overflow-wrap:anywhere}
</style>
